# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: pydantic models mirroring start.gg's API objects (Set, Game, Event, Entrant...),
# with snake_case names, UTC datetimes and char_group added. Results (winner, scores,
# seeds, placements) are included: this layer is complete on purpose (Site notes, client.py).
# Usage: returned by ds.data.raw.startgg.api functions.
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt

from pydantic import BaseModel, Field

__all__ = [
    "Character",
    "Entrant",
    "EntrantsPage",
    "Event",
    "Game",
    "PageInfo",
    "Player",
    "Selection",
    "Set",
    "SetSide",
    "SetsPage",
    "Stage",
    "Tournament",
    "TournamentsPage",
]


class Character(BaseModel):
    """One of a videogame's characters"""

    id: int = Field(description="start.gg character id, eg 1297")
    name: str = Field(description="start.gg's display name, eg 'Little Mac'")
    # start.gg knows the pick, not the fighter: 'Pokemon Trainer' is 'pokemon_trainer', ie
    # three char.parquet rows (join on its `char_group` column); None for 'Random Character'
    char_group: str | None = Field(None, description="char.parquet `char_group`, eg 'little_mac', 'pokemon_trainer'")
    char_icon: str | None = Field(None, description="Icon path under pkgs/ds/data/, eg 'char_icons/little_mac.png'")


class Stage(BaseModel):
    """A stage a game was played on"""

    id: int
    name: str = Field(description="eg 'Pokémon Stadium 2'")


class Player(BaseModel):
    """A start.gg player: the same person across every tournament"""

    id: int = Field(description="start.gg player id, eg 158026")
    tag: str = Field(description="Gamer tag without the sponsor prefix, eg 'Sparg0'")
    prefix: str | None = Field(None, description="Sponsor / team prefix, eg 'FaZe'")
    user_slug: str | None = Field(None, description="Profile slug, eg 'user/abc123' (start.gg/user/abc123)")


class Tournament(BaseModel):
    """A tournament; its `events` are the brackets inside it"""

    id: int
    name: str
    slug: str = Field(description="eg 'tournament/genesis-9'; start.gg/<slug> is its page")
    start_at: dt.datetime | None = None
    end_at: dt.datetime | None = None
    city: str | None = None
    state: str | None = Field(None, description="State / province code, eg 'MD'")
    country: str | None = Field(None, description="Two-letter country code, eg 'US'")
    venue: str | None = None
    online: bool | None = None
    num_attendees: int | None = None
    events: list[Event] = Field(default_factory=list, description="Filled by tournament searches only")


class Event(BaseModel):
    """One bracket of a tournament, eg 'Ultimate Singles'"""

    id: int
    name: str
    slug: str = Field(description="eg 'tournament/genesis-9/event/ultimate-singles'")
    start_at: dt.datetime | None = None
    online: bool | None = None
    num_entrants: int | None = None
    videogame_id: int | None = Field(None, description="1386 is Super Smash Bros. Ultimate")
    tournament: Tournament | None = None


class Selection(BaseModel):
    """The character one side picked for one game"""

    entrant_id: int
    character: Character


class Game(BaseModel):
    """One game of a set. Stage and selections are optional when a set is reported"""

    number: int = Field(description="1 for the first game of the set")
    winner_entrant_id: int | None = None
    stage: Stage | None = None
    selections: list[Selection] = Field(default_factory=list, description="[] when no characters were reported")
    entrant1_score: int | None = Field(None, description="Stocks left for the first slot's entrant")
    entrant2_score: int | None = None

    def character_of(self, entrant_id: int | None) -> Character | None:
        """The character this entrant played in this game, if reported"""
        return next((s.character for s in self.selections if s.entrant_id == entrant_id), None)


class SetSide(BaseModel):
    """One side of a set: an entrant, with its players and its result in this set"""

    entrant_id: int | None = None
    name: str | None = Field(None, description="Name as in the bracket, eg 'FaZe | Sparg0'")
    players: list[Player] = Field(default_factory=list, description="One for singles, two for doubles")
    seed: int | None = Field(None, description="Entrant's seed in the event's first phase")
    disqualified: bool | None = None
    score: float | None = Field(None, description="Games won in this set; -1 marks a DQ")
    placement: int | None = Field(None, description="Within this set: 1 = winner, 2 = loser")


class Set(BaseModel):
    """One set (match) between two entrants"""

    id: str
    completed_at: dt.datetime | None = None
    round_text: str | None = Field(None, description="eg 'Winners Semi-Final'")
    round: int | None = Field(None, description="Round number; negative is the losers bracket")
    total_games: int | None = Field(None, description="Games the set is played to, when the organizer set it")
    winner_entrant_id: int | None = None
    display_score: str | None = Field(None, description="eg 'Sparg0 3 - acola 1', or 'DQ'")
    vod_url: str | None = None
    state: int | None = Field(None, description="start.gg activity state: 1 created, 2 active, 3 completed")
    event: Event | None = None
    sides: list[SetSide] = Field(default_factory=list)
    games: list[Game] = Field(default_factory=list, description="[] when only the set score was reported")

    def side_of(self, player_id: int) -> SetSide | None:
        """The side this player was on"""
        return next((s for s in self.sides if any(p.id == player_id for p in s.players)), None)

    def opponent_of(self, player_id: int) -> SetSide | None:
        """The side this player faced"""
        mine = self.side_of(player_id)
        return next((s for s in self.sides if s is not mine), None) if mine else None


class PageInfo(BaseModel):
    """start.gg's paging block for a list"""

    total: int = 0
    total_pages: int = 0
    page: int = 1
    per_page: int = 0


class SetsPage(BaseModel):
    """One page of a player's sets, newest first, exactly as start.gg pages them"""

    page_info: PageInfo
    sets: list[Set]


class Entrant(BaseModel):
    """One entrant of an event"""

    id: int
    name: str | None = None
    players: list[Player] = Field(default_factory=list)
    seed: int | None = None
    disqualified: bool | None = None
    placement: int | None = Field(None, description="Standing in the event so far; final once the event ends")


class EntrantsPage(BaseModel):
    """One page of an event's entrants (or standings, ordered by placement)"""

    event: Event
    page_info: PageInfo
    entrants: list[Entrant]


class TournamentsPage(BaseModel):
    """One page of a tournament search"""

    page_info: PageInfo
    tournaments: list[Tournament]


